class Inventory:
    def __init__(self):
        self.stock = {}

    def add(self, name, qty):
        self.stock[name] = self.stock.get(name, 0) + qty

    def remove(self, name, qty):
        if self.stock.get(name, 0) >= qty:
            self.stock[name] -= qty
            return True
        return False

    def count(self, name):
        return self.stock.get(name, 0)

setup:
def run_ops(obj, steps):
    out = []
    for step in steps:
        name, *args = step
        r = getattr(obj, name)(*args)
        if r is not None:
            out.append(r)
    return out
